<script setup lang="ts">
import {ref,onBeforeUnmount,watch} from 'vue'
import {request} from '@/api/client'
import type {PersonalAiSetting} from '@/types/personal'
const props=defineProps<{setting:PersonalAiSetting;disabled:boolean}>(),busy=ref(false),error=ref(''),approved=ref(false)
const preview=ref<{token:string;request:string;endpoint:string;model:string}>(),result=ref<{success:boolean;code:string;message:string;milliseconds:number;models:string[];inputTokens:number|null;outputTokens:number|null;usageStatus:string}>()
let active=true,epoch=0;onBeforeUnmount(()=>{active=false;epoch++});watch(()=>props.setting.revision,()=>{epoch++;preview.value=undefined;result.value=undefined;approved.value=false})
async function prepare(mode:string){if(busy.value||props.disabled)return;const version=++epoch;busy.value=true;error.value='';result.value=undefined;approved.value=false;try{const p=await request<typeof preview.value>(`/personal-ai/settings/${props.setting.provider}/diagnostics/preview`,{method:'POST',body:JSON.stringify({mode})});if(active&&version===epoch)preview.value=p}catch(e){if(active&&version===epoch)error.value=(e as Error).message}finally{if(active&&version===epoch)busy.value=false}}
async function execute(){if(!preview.value||!approved.value||busy.value)return;const version=epoch,token=preview.value.token;busy.value=true;error.value='';preview.value=undefined;try{const r=await request<typeof result.value>('/personal-ai/settings/diagnostics/execute',{method:'POST',body:JSON.stringify({token,confirmed:true})});if(active&&version===epoch)result.value=r}catch(e){if(active&&version===epoch)error.value=(e as Error).message}finally{if(active&&version===epoch)busy.value=false}}
</script>
<template><section class="ai-diagnostics"><h4>检查已保存的配置</h4><p>模型目录和连接测试分别检查。发送前会显示请求内容；不会携带个人记忆、笔记或文件。</p><div><button type="button" class="button button--ghost button--small" :disabled="busy||disabled||!setting.configured||!setting.enabled" @click="prepare('MODELS')">查询模型目录</button><button type="button" class="button button--ghost button--small" :disabled="busy||disabled||!setting.configured||!setting.enabled" @click="prepare('CONNECTION')">测试当前模型</button></div><p v-if="busy" role="status">正在检查…</p><p v-if="error" class="form-error" role="alert">{{error}}</p><div v-if="preview" class="diagnostic-preview"><strong>{{preview.model}}</strong><code>{{preview.endpoint}}</code><p>{{preview.request}}</p><label><input v-model="approved" type="checkbox" />我确认发送这个检查请求</label><button type="button" class="button button--dark button--small" :disabled="!approved||busy" @click="execute">确认检查</button><button type="button" class="table-action" :disabled="busy" @click="preview=undefined">取消</button></div><div v-if="result" :class="{'form-error':!result.success}" role="status"><p>{{result.message}} · {{result.milliseconds}} ms</p><p v-if="result.inputTokens!=null">输入 {{result.inputTokens}} / 输出 {{result.outputTokens??'未返回'}} tokens</p><p v-if="result.usageStatus==='UNCONFIRMED'">使用记录保存情况未确认，请查看供应商账单。</p><details v-if="result.models.length"><summary>模型目录 · {{result.models.length}}</summary><ul><li v-for="model in result.models" :key="model"><code>{{model}}</code></li></ul></details></div></section></template>
<style scoped>.ai-diagnostics{border-top:1px solid var(--line);padding:24px 0;margin-top:24px}p{font-size:13px;line-height:1.8;color:var(--muted)}.ai-diagnostics>div{display:flex;gap:12px;flex-wrap:wrap}.diagnostic-preview{display:grid!important;padding:20px;border:1px solid var(--line);margin-top:20px}code{overflow-wrap:anywhere}ul{max-height:240px;overflow:auto;padding-left:20px}summary{cursor:pointer;color:var(--green)}</style>
